// Personas en una tienda (19-oct, Botillería): el primer plano les cortaba la cabeza; van en plano medio, igual desenfocado.
const PERSONAS = /\b(people|persons?|team|group|crowd|adults?|men|man|women|woman|owners?|customers?|clients?|couple|family|staff|employees?|friends?|colleagues?)\b/i;
